// ============================================================
// LICC SHILOH 10-DAY EMAIL CAMPAIGN
// PRODUCTION EMAIL ROUTING
// TIMEZONE: AFRICA/LAGOS
// ============================================================
//
// EMAIL TYPES:
//   advance_reminder
//   pre_service_reminder
//   post_service
//
// RULE:
//   Only the relevant campaign day is processed.
//
//   ADVANCE:
//   Tomorrow's service only.
//
//   PRE-SERVICE:
//   Today's service only.
//
//   POST-SERVICE:
//   Today's service only.
// ============================================================


const results = [];

const now = new Date();


// ============================================================
// CURRENT NIGERIA TIME
// ============================================================

const nigeriaParts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Africa/Lagos',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false
}).formatToParts(now);

const current = {};

for (const part of nigeriaParts) {
  if (part.type !== 'literal') {
    current[part.type] = part.value;
  }
}

const currentYear = Number(current.year);
const currentMonth = Number(current.month);
const currentDay = Number(current.day);
const currentHour = Number(current.hour);
const currentMinute = Number(current.minute);
const currentSecond = Number(current.second);


// ============================================================
// DATE KEY HELPER
// ============================================================

function dateKey(year, month, day) {
  return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
}


// ============================================================
// TODAY
// ============================================================

const todayKey = dateKey(
  currentYear,
  currentMonth,
  currentDay
);


// ============================================================
// TOMORROW
// ============================================================

const tomorrowDate = new Date(
  Date.UTC(
    currentYear,
    currentMonth - 1,
    currentDay
  )
);

tomorrowDate.setUTCDate(
  tomorrowDate.getUTCDate() + 1
);

const tomorrowKey = dateKey(
  tomorrowDate.getUTCFullYear(),
  tomorrowDate.getUTCMonth() + 1,
  tomorrowDate.getUTCDate()
);


// ============================================================
// PARSE SHEET DATE
// Example: 28-Aug-2026
// ============================================================

function parseDate(value) {

  if (!value) return null;

  const match = String(value)
    .trim()
    .match(/^(\d{1,2})-([A-Za-z]{3})-(\d{4})$/);

  if (!match) return null;

  const months = {
    jan: 1,
    feb: 2,
    mar: 3,
    apr: 4,
    may: 5,
    jun: 6,
    jul: 7,
    aug: 8,
    sep: 9,
    oct: 10,
    nov: 11,
    dec: 12
  };

  const month = months[match[2].toLowerCase()];

  if (!month) return null;

  return {
    year: Number(match[3]),
    month: month,
    day: Number(match[1])
  };
}


// ============================================================
// PARSE SHEET TIME
// Examples:
// 5:30 PM
// 10:30 AM
// ============================================================

function parseTime(value) {

  if (!value) return null;

  const match = String(value)
    .trim()
    .toUpperCase()
    .match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/);

  if (!match) return null;

  let hour = Number(match[1]);
  const minute = Number(match[2]);
  const ampm = match[3];

  if (ampm === 'AM' && hour === 12) {
    hour = 0;
  }

  if (ampm === 'PM' && hour !== 12) {
    hour += 12;
  }

  return {
    hour,
    minute
  };
}


// ============================================================
// CONVERT DATE/TIME TO COMPARISON MINUTES
// ============================================================

function toMinutes(year, month, day, hour, minute) {

  return Date.UTC(
    year,
    month - 1,
    day,
    hour,
    minute,
    0,
    0
  ) / 60000;
}


// ============================================================
// CURRENT TIME
// ============================================================

const currentMinutes = toMinutes(
  currentYear,
  currentMonth,
  currentDay,
  currentHour,
  currentMinute
);


// ============================================================
// PROCESS CAMPAIGN ROWS
// ============================================================

for (const item of $input.all()) {

  const row = item.json;

  const dateParts = parseDate(row['Date']);
  const timeParts = parseTime(row['Service Time']);

  if (!dateParts || !timeParts) {
    continue;
  }


  // ----------------------------------------------------------
  // SERVICE DATE KEY
  // ----------------------------------------------------------

  const serviceDateKey = dateKey(
    dateParts.year,
    dateParts.month,
    dateParts.day
  );


  // ----------------------------------------------------------
  // SERVICE TIME
  // ----------------------------------------------------------

  const serviceMinutes = toMinutes(
    dateParts.year,
    dateParts.month,
    dateParts.day,
    timeParts.hour,
    timeParts.minute
  );


  // ----------------------------------------------------------
  // EMAIL WINDOWS
  // ----------------------------------------------------------

  const advanceStart =
    serviceMinutes - (24 * 60);

  const advanceEnd =
    serviceMinutes - (2 * 60);

  const preServiceStart =
    serviceMinutes - (2 * 60);

  const preServiceEnd =
    serviceMinutes - (90);


  // ----------------------------------------------------------
  // CURRENT STATUS
  // ----------------------------------------------------------

  const advanceStatus =
    String(row['Advance Reminder'] || '')
      .trim()
      .toLowerCase();

  const preServiceStatus =
    String(row['Pre-Service Reminder'] || '')
      .trim()
      .toLowerCase();

  const postServiceReady =
    String(row['Post-Service Ready'] || '')
      .trim()
      .toLowerCase();

  const postServiceSentAt =
    String(row['Post-Service Sent At'] || '')
      .trim();


  // ----------------------------------------------------------
  // EMAIL TYPE
  // ----------------------------------------------------------

  let emailType = null;


  // ==========================================================
  // 1. ADVANCE REMINDER
  // ONLY TOMORROW'S SERVICE
  // ==========================================================

  if (
    advanceStatus !== 'sent' &&
    serviceDateKey === tomorrowKey &&
    currentMinutes >= advanceStart &&
    currentMinutes < advanceEnd
  ) {

    emailType = 'advance_reminder';

  }


  // ==========================================================
  // 2. PRE-SERVICE REMINDER
  // ONLY TODAY'S SERVICE
  // ==========================================================

  else if (
    preServiceStatus !== 'sent' &&
    serviceDateKey === todayKey &&
    currentMinutes >= preServiceStart &&
    currentMinutes < preServiceEnd
  ) {

    emailType = 'pre_service_reminder';

  }


  // ==========================================================
  // 3. POST-SERVICE
  // ONLY TODAY'S SERVICE
  // ==========================================================

  else if (
    postServiceReady === 'ready' &&
    postServiceSentAt === '' &&
    serviceDateKey === todayKey &&
    currentMinutes >= serviceMinutes
  ) {

    emailType = 'post_service';

  }


  // ==========================================================
  // OUTPUT ONLY WHEN SOMETHING IS DUE
  // ==========================================================

  if (emailType) {

    results.push({
      json: {

        ...row,

        emailType,

        testMode: false,

        nigeriaDate: todayKey,

        nigeriaTime:
          `${String(currentHour).padStart(2, '0')}:${String(currentMinute).padStart(2, '0')}:${String(currentSecond).padStart(2, '0')}`,

        serviceDate:
          serviceDateKey,

        serviceTime:
          `${String(timeParts.hour).padStart(2, '0')}:${String(timeParts.minute).padStart(2, '0')}`,

        isCurrentlyInAdvanceWindow:
          currentMinutes >= advanceStart &&
          currentMinutes < advanceEnd,

        isCurrentlyInPreServiceWindow:
          currentMinutes >= preServiceStart &&
          currentMinutes < preServiceEnd,

        isPostServiceWindow:
          currentMinutes >= serviceMinutes
      }
    });
  }
}


return results;
